    ],
    "lacunas": [
      "A duração nova de usinar corpo pode ser qualquer inteiro não negativo.",
      "As precedências são referidas, mas seus vínculos não estão expostos na view; não é possível determinar o efeito sobre o marco final."
    ],
    "motivo": "A duração alterada não foi fixada e os vínculos necessários para calcular o término não estão disponíveis.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_a781",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A duração nova pode ser menor ou maior que os 4 dias originais, e as precedências que determinariam o efeito no marco final não estão expostas."
    ],
    "motivo": "Não se pode concluir se o término será antecipado, atrasado ou mantido.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Custo da linha base declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O valor de eventual extensão de apoio depende do término novo, que não pode ser determinado."
    ],
    "motivo": "Inclui cobrança adicional certa de 2.500 centavos; o apoio preserva o valor base se houver antecipação e pode gerar extensão adicional se houver atraso.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "Magnitude do eventual custo adicional de apoio depende do término novo; não há crédito de apoio por antecipação."
    ],
    "motivo": "A cobrança direta de 2.500 centavos é certa e o apoio não pode ficar abaixo do valor da linha base; eventual atraso pode aumentar o custo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A duração nova de usinar corpo e as precedências necessárias para calcular o marco final não estão suficientemente determinadas, então a variação do término não pode ser estimada em dias nem ter direção afirmada. O custo, porém, aumenta ao menos 2.500 centavos pela cobrança direta; o montante exato depende de eventual extensão do apoio."
}

